#!/usr/bin/env bash
# Generated by install.sh. Pin the verified runtime across non-interactive shells.
PINNED_BUN="__BUN_BIN__"
MIN_BUN_VERSION="__MIN_BUN_VERSION__"
CLI_JS="__CLI_JS__"

# Release builds embed Bun and OpenTUI. JavaScript builds retain the pinned
# runtime fallback for development and recovery.
NATIVE_BINARY="${CLI_JS%/cli.js}/pappardelle"
if [[ -x "$NATIVE_BINARY" ]]; then
    exec "$NATIVE_BINARY" "$@"
fi

BUN_BIN="$PINNED_BUN"
if [[ ! -x "$BUN_BIN" ]]; then
    BUN_BIN="$(command -v bun || true)"
fi
VERSION="$("$BUN_BIN" --version 2>/dev/null || true)"
SUPPORTED=false
if [[ "$VERSION" =~ ^([0-9]+)\.([0-9]+)\.([0-9]+)$ ]]; then
    IFS=. read -r MAJOR MINOR PATCH <<<"$VERSION"
    IFS=. read -r MIN_MAJOR MIN_MINOR MIN_PATCH <<<"$MIN_BUN_VERSION"
    if (( MAJOR > MIN_MAJOR || (MAJOR == MIN_MAJOR && MINOR > MIN_MINOR) ||
          (MAJOR == MIN_MAJOR && MINOR == MIN_MINOR && PATCH >= MIN_PATCH) )); then
        SUPPORTED=true
    fi
fi
if [[ "$SUPPORTED" != true ]]; then
    echo "pappardelle: Bun at ${BUN_BIN:-$PINNED_BUN} is ${VERSION:-unavailable}; >= $MIN_BUN_VERSION is required." >&2
    echo "  Reinstall to pin a supported runtime:" >&2
    echo "    curl -fsSL https://raw.githubusercontent.com/chardigio/pappardelle/main/install.sh | bash" >&2
    exit 1
fi
if [[ ! -f "$CLI_JS" ]]; then
    echo "pappardelle: $CLI_JS is missing; rebuild or reinstall Pappardelle." >&2
    exit 1
fi
# Keep a workspace's .env and bunfig.toml preload out of Pappardelle.
exec "$BUN_BIN" --no-env-file --config=/dev/null "$CLI_JS" "$@"
